import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * Narrows the customer list by name and by status.
 *
 * <p>A customer matches when it satisfies both parts. The name is split on
 * whitespace into terms, and every term must appear, ignoring case and accents,
 * in the first name or in the last name. An empty set of statuses matches every
 * status.
 *
 * @param name     the text typed into the name filter; blank matches every name
 * @param statuses the statuses to show; empty shows every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
    }

    /** Returns a test that accepts exactly the customers this filter matches. */
    public Predicate<Customer> toPredicate() {
        List<String> terms = searchTerms(name);
        return customer -> {
            if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
                return false;
            }
            String firstName = normalize(customer.firstName());
            String lastName = normalize(customer.lastName());
            return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
        };
    }

    private static List<String> searchTerms(String text) {
        return WHITESPACE.splitAsStream(normalize(text).strip())
                .filter(term -> !term.isEmpty())
                .toList();
    }

    /** Lower-cases the text and strips accents, so that {@code Mäkinen} becomes {@code makinen}. */
    private static String normalize(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
