+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import org.junit.jupiter.api.AfterAll;
+import org.junit.jupiter.api.BeforeAll;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+/**
+ * Drives the running application in a real headless Chromium, offline. Checks what
+ * the address bar says and what typing costs the backend, which Karibu cannot see.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserTest {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @BeforeAll
+    static void launchBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+    }
+
+    @AfterAll
+    static void closeBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    private Page openView(String query) {
+        Page page = browser.newPage();
+        page.navigate("http://localhost:" + port + "/" + query);
+        assertThat(page.locator("vaadin-grid")).isVisible();
+        return page;
+    }
+
+    private static Locator nameField(Page page) {
+        return page.locator("vaadin-text-field input");
+    }
+
+    private static Locator summary(Page page, String text) {
+        return page.getByText(text, new Page.GetByTextOptions().setExact(true));
+    }
+
+    @Test
+    void urlParametersFillTheFieldsAndFilterTheList() {
+        Page page = openView("?name=vir&status=ACTIVE,CLOSED");
+
+        assertThat(nameField(page)).hasValue("vir");
+        assertThat(summary(page, "Showing 10 of 500")).isVisible();
+        page.close();
+    }
+
+    @Test
+    void typingNarrowsTheListWithAFewQueriesAndUpdatesTheAddressBar() {
+        Page page = openView("");
+        queryLog.clear();
+
+        Locator name = nameField(page);
+        name.click();
+        name.pressSequentially("ada aal", new Locator.PressSequentiallyOptions().setDelay(0));
+
+        assertThat(summary(page, "Showing 2 of 500")).isVisible();
+        assertThat(page).hasURL(Pattern.compile(".*\\?name=ada(\\+|%20)aal$"));
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "typing cost " + queryLog.countQueries().size() + " count queries");
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "typing cost " + queryLog.pageQueries().size() + " page queries");
+        page.close();
+    }
+
+    @Test
+    void clearingTheNameRemovesItFromTheAddressBar() {
+        Page page = openView("?name=ada");
+        assertThat(summary(page, "Showing 13 of 500")).isVisible();
+
+        nameField(page).fill("");
+
+        assertThat(summary(page, "Showing 500 of 500")).isVisible();
+        assertThat(page).hasURL(Pattern.compile("^[^?]*$"));
+        page.close();
+    }
+
+    @Test
+    void choosingAStatusUpdatesTheAddressBar() {
+        Page page = openView("");
+
+        page.locator("vaadin-multi-select-combo-box input").click();
+        page.locator("vaadin-multi-select-combo-box-item",
+                new Page.LocatorOptions().setHasText("PENDING")).click();
+        page.keyboard().press("Escape");
+
+        assertThat(summary(page, "Showing 167 of 500")).isVisible();
+        assertThat(page).hasURL(Pattern.compile(".*\\?status=PENDING$"));
+        page.close();
+    }
+
+    @Test
+    void statusInTheAddressBarSelectsTheStatus() {
+        Page page = openView("?status=CLOSED");
+
+        assertThat(summary(page, "Showing 166 of 500")).isVisible();
+        assertThat(page.locator("vaadin-multi-select-combo-box")).containsText("CLOSED");
+        page.close();
+    }
+}
